cypress_script:
describe('Dropdown Selection Tests', () => {
  it('should select Option 1 from the dropdown', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('1');
    cy.get('#dropdown').should('have.value', '1');
  });

  it('should not allow selection of an empty option', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('');
    cy.get('#dropdown').should('have.value', '');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Dropdown Selection Tests', () => {
  test('should select Option 1 from the dropdown', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', '1');
    const selectedValue = await page.$eval('#dropdown', el => el.value);
    test.expect(selectedValue).toBe('1');
  });

  test('should not allow selection of an empty option', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', '');
    const selectedValue = await page.$eval('#dropdown', el => el.value);
    test.expect(selectedValue).toBe('');
  });
});
